/**
 * DIVERSE video bookmarks: the panel under the video of an activity.
 *
 * The video is the first one on the page the script can control: a video.js player (uploaded videos, and YouTube
 * when video.js plays it) or a plain video element. Without one the panel stays hidden.
 *
 * @module     local_diverse_videonotes/notes
 * @copyright  2026 DIVERSE European University
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('local_diverse_videonotes/notes', ['core/ajax', 'core/notification'], function(Ajax, Notification) {

    /**
     * A moment as m:ss or h:mm:ss.
     *
     * @param {Number} seconds
     * @return {String}
     */
    var format = function(seconds) {
        seconds = Math.max(0, Math.floor(seconds));
        var h = Math.floor(seconds / 3600);
        var m = Math.floor((seconds % 3600) / 60);
        var s = seconds % 60;
        var two = function(n) {
            return (n < 10 ? '0' : '') + n;
        };
        return h ? h + ':' + two(m) + ':' + two(s) : m + ':' + two(s);
    };

    /**
     * A uniform way to read and set the time of the video, whichever player it is in.
     *
     * @param {HTMLElement} root The page's main region.
     * @return {Object|null} time(), seek(seconds), element; null if no video can be controlled yet.
     */
    var findPlayer = function(root) {
        var vjs = root.querySelector('.video-js');
        if (vjs && vjs.player) {
            var player = vjs.player;
            return {
                element: vjs.closest('.mediaplugin') || vjs,
                time: function() {
                    return player.currentTime() || 0;
                },
                seek: function(seconds) {
                    player.currentTime(seconds);
                    var played = player.play();
                    if (played && played.catch) {
                        played.catch(function() {
                            // The browser may ask for a click first: the video stays at the moment, paused.
                        });
                    }
                }
            };
        }
        var video = root.querySelector('video');
        if (video && !(vjs && !vjs.player)) {
            return {
                element: video.closest('.mediaplugin') || video,
                time: function() {
                    return video.currentTime || 0;
                },
                seek: function(seconds) {
                    video.currentTime = seconds;
                    var played = video.play();
                    if (played && played.catch) {
                        played.catch(function() {
                            // As above.
                        });
                    }
                }
            };
        }
        return null;
    };

    /**
     * Show the panel under the video and connect it.
     *
     * @param {Number} cmid
     * @param {Object} player See findPlayer().
     * @param {HTMLElement} panel
     */
    var start = function(cmid, player, panel) {
        var list = panel.querySelector('[data-region="list"]');
        var empty = panel.querySelector('[data-region="empty"]');
        var form = panel.querySelector('[data-region="form"]');
        var input = panel.querySelector('[data-region="note"]');
        var now = panel.querySelector('[data-region="now"]');
        var template = panel.querySelector('template[data-region="item"]');

        // Under the theme's player frame if the video is in it, else right under the video.
        var frame = player.element.closest('.diverse-player') || player.element;
        frame.insertAdjacentElement('afterend', panel);
        panel.hidden = false;

        var render = function(notes) {
            list.innerHTML = '';
            notes.forEach(function(note) {
                var item = template.content.firstElementChild.cloneNode(true);
                item.dataset.id = note.id;
                item.dataset.position = note.position;
                item.querySelector('[data-region="time"]').textContent = format(note.position);
                item.querySelector('[data-region="text"]').textContent = note.note;
                list.appendChild(item);
            });
            empty.hidden = notes.length > 0;
        };

        var call = function(methodname, args) {
            return Ajax.call([{methodname: methodname, args: args}])[0];
        };

        var load = function() {
            return call('local_diverse_videonotes_get_notes', {cmid: cmid}).then(render).catch(Notification.exception);
        };

        // The button shows the moment it will mark.
        setInterval(function() {
            now.textContent = format(player.time());
        }, 500);

        form.addEventListener('submit', function(e) {
            e.preventDefault();
            var position = Math.floor(player.time());
            call('local_diverse_videonotes_add_note', {cmid: cmid, position: position, note: input.value})
                .then(function() {
                    input.value = '';
                    return load();
                })
                .catch(Notification.exception);
        });

        list.addEventListener('click', function(e) {
            var item = e.target.closest('li');
            if (!item) {
                return;
            }
            if (e.target.closest('[data-action="delete"]')) {
                call('local_diverse_videonotes_delete_note', {id: Number(item.dataset.id)})
                    .then(load)
                    .catch(Notification.exception);
            } else if (e.target.closest('[data-action="jump"]')) {
                player.seek(Number(item.dataset.position));
            }
        });

        load();
    };

    return {
        /**
         * Wait for the video's player (video.js starts after the page) and connect the panel to it.
         *
         * @param {Number} cmid
         */
        init: function(cmid) {
            var panel = document.querySelector('.local-diverse-videonotes');
            var root = document.querySelector('#region-main') || document.body;
            if (!panel) {
                return;
            }
            var tries = 0;
            var wait = setInterval(function() {
                var player = findPlayer(document.querySelector('.diverse-player') || root) || findPlayer(root);
                if (player) {
                    clearInterval(wait);
                    start(cmid, player, panel);
                } else if (++tries > 40) {
                    clearInterval(wait);
                }
            }, 250);
        }
    };
});
